nus();				// Always call the inherited method first	for (CommandNumber theCommandNum = cFirstWindow; theCommandNum <= cLastWindow; theCommandNum++)		::Enable(theCommandNum, true);}//----------------------------------------------------------------------------------------// TSSApplication::MakeAWindow//----------------------------------------------------------------------------------------bool TSSApplication::MakeAWindow(CommandNumber aWindowNumber){	bool	windowMade = false;	// Try to make a new window based on the command number.	if (aWindowNumber >= cFirstWindow && aWindowNumber <= cLastWindow)	{		TWindow* aWindow = gViewServer->NewTemplateWindow(aWindowNumber, NULL);		::ThrowIfNULL_AC(aWindow);		/*		TSSView* aSSView = (TSSView*) (aWindow->FindSubView('SKEL'));	// Must cast because FindSubView returns TView		TStdPrintHandler* aHandler = TH_new TStdPrintHandler(this,		// its document 								   aSSView,	// its view 								   kFixedSize,		// horzontal page size is fixed 								   kFixedSize);		// vertical page size is fixed		*/		aWindow->Open();		windowMade = true;	}	return windowMade;}//----------------------------------------------------------------------------------------// End of USSApplication.cp